<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import CoalToolShell from '../components/CoalToolShell.vue'
import CoalSourceTable from '../components/CoalSourceTable.vue'
import { lines, targetFor, examples, newCoal, optimize, validateCoal, type Coal, type BlendResult, type Target } from '../utils/coal/blending'
import { readLocal, writeLocal, records, saveRecord, downloadCSV, format } from '../utils/coal/storage'
const route=useRoute(),line=computed(()=>lines.find(l=>l.id===route.params.line)),lineId=computed(()=>line.value?.id||'dianmei')
const coals=ref<Coal[]>([]),target=ref(targetFor('dianmei')),report=ref<BlendResult|null>(null),error=ref(''),message=ref(''),mode=ref('多煤掺配')
const key=()=>`kuang:coal:sources:v1:${lineId.value}`
watch(()=>route.fullPath,()=>{document.title=`${line.value?.name||'配煤专区'} · 懂矿帝`;coals.value=examples(lineId.value);target.value=targetFor(lineId.value);report.value=null;error.value='';message.value='';mode.value='多煤掺配';if(route.query.record){const rec=records().find(r=>r.id===route.query.record);if(rec?.input&&typeof rec.input==='object'){const data=rec.input as {coals:Coal[];target:Target};if(Array.isArray(data.coals)&&data.target){coals.value=data.coals;target.value=data.target}}}},{immediate:true})
watch([coals,target,mode],()=>{report.value=null;error.value='';message.value=''},{deep:true,flush:'sync'})
const isDry=computed(()=>['shuimeijiang','jiaomei','penchuimei'].includes(lineId.value))
const targetFields=computed(()=>[
 ...(lineId.value==='jiaomei'?[]:[{key:'q',label:lineId.value==='shuimeijiang'?'干基热值 Qnet,d':lineId.value==='penchuimei'?'最低热值 Qnet,ar':'目标热值 Qnet,ar',unit:'kcal/kg'},...(lineId.value==='penchuimei'?[]:[{key:'tolerance',label:'热值允许浮动 ±',unit:'kcal/kg'}])]),
 ...(lineId.value==='shuimeijiang'?[]:[{key:'m',label:'全水分 Mt ≤',unit:'%'}]),{key:'a',label:'干基灰分 Ad ≤',unit:'%'},{key:'s',label:'干基全硫 St,d ≤',unit:'%'},{key:'vmin',label:'挥发分 Vdaf ≥',unit:'%'},{key:'vmax',label:'挥发分 Vdaf ≤',unit:'%'},
 ...(lineId.value==='huagong'?[{key:'fc',label:'固定碳 FC,d ≥',unit:'%'},{key:'st',label:'逐煤灰熔点 ST ≥',unit:'℃'},{key:'ts',label:'逐煤热稳 TS+6 ≥',unit:'%'},{key:'ss',label:'逐煤抗碎 SS ≥',unit:'%'}]:[]),
 ...(lineId.value==='jiaomei'?[{key:'g',label:'估算粘结指数 G ≥',unit:''},{key:'y',label:'估算胶质层 Y ≥',unit:'mm'},{key:'weak',label:'弱 / 未知粘结煤占比 ≤',unit:'%'},{key:'strong',label:'强粘结煤占比 ≥',unit:'%'}]:[]),
 ...(lineId.value==='penchuimei'?[{key:'hgi',label:'估算 HGI ≥',unit:''}]:[]),...(lineId.value==='shuimeijiang'?[{key:'concentration',label:'目标浆体固含量',unit:'%'}]:[]),{key:'tonnes',label:lineId.value==='shuimeijiang'?'本单干煤采购量':'本单收到基采购量',unit:'吨'}
] as {key:keyof Target;label:string;unit:string}[])
function setTarget(key:keyof Target,event:Event){const value=(event.target as HTMLInputElement).value;(target.value as unknown as Record<string,unknown>)[key]=value===''?'':Number(value)}
function run(){report.value=null;error.value='';message.value='';try{if(mode.value==='单煤评估'&&coals.value.filter(c=>c.enabled).length!==1)throw new Error('单煤评估请仅启用一个煤源。');report.value=optimize(lineId.value,coals.value,target.value)}catch(e){error.value=e instanceof Error?e.message:'计算失败，请核对数据。'}}
function add(){const coal=newCoal();if(lineId.value==='shuimeijiang')coal.m=0;coals.value.push(coal)}
function restore(){coals.value=examples(lineId.value);target.value=targetFor(lineId.value)}
function saveSources(){try{coals.value.forEach(c=>validateCoal(c,lineId.value));writeLocal(key(),coals.value);message.value=`已将 ${coals.value.length} 条煤源保存到本机煤源库。`}catch(e){message.value=e instanceof Error?e.message:'保存失败，浏览器存储不可用。'}}
function loadSources(){const data=readLocal<unknown>(key(),null);if(!Array.isArray(data)){message.value='本机暂无该产品线的煤源。';return}try{data.forEach(c=>validateCoal(c,lineId.value));coals.value=data;message.value='已载入本机煤源库。'}catch{message.value='保存的煤源格式异常，未载入。'}}
function save(){if(!report.value)return;try{saveRecord({name:line.value!.name,path:route.path,input:{coals:coals.value,target:target.value},output:report.value});message.value='已保存完整输入和报告，可在测算记录中恢复。'}catch{message.value='本机保存失败，可导出报告。'}}
const metrics=computed(()=>report.value?[{label:'预测热值',value:report.value.q,unit:lineId.value==='shuimeijiang'?'kcal/kg · d':'kcal/kg · ar'},...(lineId.value==='shuimeijiang'?[]:[{label:'全水分 Mt',value:report.value.m,unit:'% · ar'}]),{label:'灰分 Ad',value:report.value.a,unit:'% · d'},{label:'全硫 St,d',value:report.value.s,unit:'% · d'},{label:'挥发分 Vdaf',value:report.value.v,unit:'% · daf'},...(lineId.value==='huagong'?[{label:'固定碳 FC,d',value:report.value.fc,unit:'% · d'}]:[]),...(lineId.value==='jiaomei'?[{label:'G 未修正估算',value:report.value.g??'未验证',unit:''},{label:'Y 未修正估算',value:report.value.y??'未验证',unit:'mm'}]:[]),...(lineId.value==='penchuimei'?[{label:'HGI 未修正估算',value:report.value.hgi??'未验证',unit:''}]:[])]:[])
function exportReport(){const r=report.value;if(!r)return;downloadCSV(`${line.value!.name}报告.csv`,[['懂矿帝',line.value!.name],['时间',new Date().toLocaleString('zh-CN')],['输入煤源','启用','价格','最高比例%','Q','Mt','A','St','Vdaf','灰硫基准','G','Y','HGI','ST','TS','SS','粒度','Mad'],...coals.value.map(c=>[c.name,c.enabled?'是':'否',c.price,c.cap,c.q,c.m,c.a,c.s,c.v,c.basis,c.g,c.y,c.hgi,c.st,c.ts,c.ss,c.size,c.mad]),[],['采购目标','数值'],...Object.entries(target.value).map(([k,v])=>[k,v]),[],['煤源','收到基占比%（制浆为干基）','干煤占比%','采购量t','金额元'],...r.rows.map(row=>[row.coal.name,format(row.ratio*100,6),format(row.dryRatio*100,6),format(row.tonnes,6),format(row.tonnes*row.coal.price,2)]),[],['采购吨价',r.price],['干煤吨价',r.dryPrice],['采购总额',r.price*r.total],...metrics.value.map(m=>[m.label,m.value,m.unit]),...(lineId.value==='shuimeijiang'?[['目标浓度%',r.concentration],['每吨干煤加水量t',100/r.concentration-1],['浆体低位热值kcal/kg',r.q*r.concentration/100-(1-r.concentration/100)*2300/4.1868]]:[]),...r.warnings.map(w=>['说明',w])])}
</script>
<template><CoalToolShell><template v-if="!route.params.line"><section class="coal-blend-hero"><div class="container"><p class="coal-eyebrow">矿业工具箱 / 配煤专区</p><h1>选好煤源，把成本配下来。</h1><p>设定采购目标与质量边界，在可行约束内求经济配比。<br>从每吨成本到煤质预测，让方案能够复核。</p><div class="coal-blend-pills"><span>多指标约束</span><span>干湿基口径核算</span><span>本机煤源库</span><span>CSV 报告导出</span></div></div></section><section class="container coal-section"><div class="coal-section-head"><h2>选择你的用煤场景</h2><span>5 条产品线，分别建模</span></div><div class="coal-line-grid"><RouterLink v-for="(l,i) in lines" :key="l.id" :to="`/tools/coal/${l.id}`" class="coal-line-card"><div><span class="coal-line-number">0{{i+1}}</span><span class="coal-tag">{{l.tag}}</span></div><h2>{{l.name}}</h2><p>{{l.desc}}</p><strong>进入测算 <span>→</span></strong></RouterLink></div><div class="coal-note">热值、灰分、硫分按对应质量口径核算；G/Y/HGI 为未修正估算，灰熔点不做混煤预测。示例煤源仅用于演示，并非市场报价。</div></section></template>
 <section v-else-if="line" class="container coal-section"><div class="coal-breadcrumb"><RouterLink to="/tools">工具箱</RouterLink> / <RouterLink to="/tools/coal">配煤专区</RouterLink> / {{line.short}}</div><div class="coal-detail-heading"><span class="coal-tag">{{line.tag}}</span><h1>{{line.name}}</h1><p>{{line.desc}}</p></div><div class="coal-line-tabs"><RouterLink v-for="l in lines" :key="l.id" :to="`/tools/coal/${l.id}`" :class="{active:line.id===l.id}">{{l.short}}</RouterLink></div>
 <div v-if="line.id==='shuimeijiang'" class="coal-filter"><button v-for="m in ['多煤掺配','单煤评估']" :key="m" :class="{active:mode===m}" @click="mode=m">{{m}}</button></div>
 <section class="coal-panel coal-target-panel"><div class="coal-panel-heading"><h2><span class="coal-step">01</span> 采购目标</h2><span class="coal-help">未启用的约束填 0；采购量及浓度须大于 0</span></div><div class="coal-target-grid"><label v-for="f in targetFields" :key="f.key" class="coal-field"><span>{{f.label}}</span><div class="coal-input-unit"><input type="number" step="any" min="0" :value="target[f.key]" :aria-label="f.label" @input="setTarget(f.key,$event)"><span>{{f.unit}}</span></div></label><label v-if="line.id==='huagong'" class="coal-field"><span>同档粒度互掺</span><select v-model="target.size"><option>自动</option><option>6～13mm</option><option>13～25mm</option><option>25～50mm</option></select></label></div><div class="coal-note" v-if="isDry">{{line.id==='shuimeijiang'?'价格与热值均填干煤口径；采购量为干煤量。':'价格与热值填收到基口径；求解按干煤吨成本优化，报告同时列出收到基和干煤配比。'}}</div></section>
 <section class="coal-panel coal-sources-panel"><div class="coal-panel-heading"><h2><span class="coal-step">02</span> 可用煤源</h2><span class="coal-tag">{{coals.filter(c=>c.enabled).length}} 条已启用</span></div><p class="coal-help">当前为示例数据，不代表实时报价。灰 / 硫按所选基准录入，挥发分始终为 Vdaf；上限按收到基质量占比（制浆按干煤占比）。</p><CoalSourceTable :coals="coals" :line="lineId" @remove="id=>coals=coals.filter(c=>c.id!==id)"/><div class="coal-actions"><button class="coal-btn" @click="add">＋ 添加煤源</button><button class="coal-btn" @click="saveSources">保存煤源库</button><button class="coal-btn" @click="loadSources">载入煤源库</button><button class="coal-text-button" @click="restore">恢复示例</button><button class="coal-text-button" @click="coals=[]">清空当前表格</button></div></section>
 <div class="coal-run-bar"><div><strong>在约束范围内，寻找经济配煤方案</strong><p>灰硫按干煤质量核算，Vdaf 按可燃体质量核算。</p></div><button class="coal-btn primary" @click="run">计算{{mode==='单煤评估'?'单煤指标':'经济配比'}} →</button></div><p v-if="error" class="coal-error" role="alert">{{error}}</p><p v-if="message" class="coal-feedback" role="status">{{message}}</p>
 <section class="coal-panel coal-report"><div class="coal-panel-heading"><h2><span class="coal-step">03</span> 配煤测算报告</h2><div v-if="report" class="coal-actions"><button class="coal-btn" @click="save">保存测算</button><button class="coal-btn" @click="exportReport">导出报告 CSV</button></div></div><div v-if="!report" class="coal-empty"><span class="coal-empty-icon">▤</span><h3>等待生成你的配煤方案</h3><p>核对采购目标与煤源后，点击「计算经济配比」。<br>修改任意数据后，原报告会失效，请重新计算。</p></div><template v-else><div class="coal-report-summary"><div><span>{{isDry?'干煤吨成本':'收到基吨成本'}}</span><strong>{{format(isDry?report.dryPrice:report.price)}} <small>元/吨</small></strong></div><div><span>{{line.id==='shuimeijiang'?'干煤采购总量':isDry?'收到基吨成本':'干煤吨成本'}}</span><b>{{format(line.id==='shuimeijiang'?report.total:isDry?report.price:report.dryPrice)}} {{line.id==='shuimeijiang'?'吨':'元/吨'}}</b></div><div><span>本单采购总额</span><b>{{format(report.price*report.total)}} 元</b></div><div><span>入选煤源 / 粒度</span><b>{{report.rows.length}} 种 · {{report.size}}</b></div></div><div class="coal-ratio-bar"><span v-for="(row,i) in report.rows" :key="row.coal.id" :style="{width:`${row.ratio*100}%`,background:['#176b59','#43a08a','#dea657','#697fb5','#b97661'][i%5]}">{{row.ratio>0.1?format(row.ratio*100,1)+'%':''}}</span></div><div class="coal-table-scroll"><table class="coal-report-table"><thead><tr><th>煤源</th><th>{{line.id==='shuimeijiang'?'干煤配比':'收到基配比'}}</th><th v-if="line.id!=='shuimeijiang'">干煤配比</th><th>采购量（吨）</th><th>采购单价</th><th>采购金额（元）</th></tr></thead><tbody><tr v-for="row in report.rows" :key="row.coal.id"><td>{{row.coal.name}}</td><td>{{format(row.ratio*100,3)}}%</td><td v-if="line.id!=='shuimeijiang'">{{format(row.dryRatio*100,3)}}%</td><td>{{format(row.tonnes,3)}}</td><td>{{format(row.coal.price)}}</td><td>{{format(row.tonnes*row.coal.price)}}</td></tr></tbody></table></div><h3>配后指标预测</h3><div class="coal-metrics"><div v-for="metric in metrics" :key="metric.label"><span>{{metric.label}}</span><strong>{{format(metric.value)}} <small>{{metric.unit}}</small></strong></div></div><template v-if="line.id==='shuimeijiang'"><h3>按目标固含量的浆体核算</h3><div class="coal-metrics"><div><span>设定浓度（非预测值）</span><strong>{{report.concentration}}%</strong></div><div><span>每吨干煤需添加水</span><strong>{{format(100/report.concentration-1,4)}} <small>吨</small></strong></div><div><span>浆体低位热值（含水汽化修正）</span><strong>{{format(report.q*report.concentration/100-(1-report.concentration/100)*2300/4.1868)}} <small>kcal/kg</small></strong></div><div><span>黏度 / 可达浓度</span><strong>待制浆试验</strong></div></div></template><div v-for="warning in report.warnings" :key="warning" class="coal-note">{{warning}}</div><p class="coal-help">采用未修约数据求解，表内显示值存在尾差。此报告仅用于采购测算，配后实际煤质、工艺适应性以混煤试验、合同与检验结果为准。</p></template></section>
 </section><section v-else class="container coal-empty"><h1>未找到该配煤产品线</h1><RouterLink to="/tools/coal">返回配煤专区</RouterLink></section></CoalToolShell></template>
